import {activeOrganization} from './organization.js';
import {activityEvents,normalizeWorkflow,periodKey,periodLabel} from './personal-workflows.js';

const safe=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const labels={email:'E-mails déclarés',linkedin:'Approches LinkedIn déclarées',action:'Actions terminées',meeting:'Rendez-vous tenus'};
const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const csv=value=>`"${(/^[=+\-@]/.test(String(value).trim())?"'":'')+String(value??'').replaceAll('"','""')}\"`;
export const reportCompanyKey=value=>String(value||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('fr');
export const reportsForCompany=(reports,companyName)=>Array.isArray(reports)&&reportCompanyKey(companyName)?reports.filter(report=>reportCompanyKey(report?.companyName)===reportCompanyKey(companyName)):[];
export function formatReportTimestamp(iso){
  const date=new Date(iso);
  return Number.isNaN(date.valueOf())?'Date indisponible':new Intl.DateTimeFormat('fr-FR',{dateStyle:'long',timeStyle:'short',timeZone:'Europe/Paris'}).format(date);
}

export function buildActivityReport(workflow,organization,period='week',{city='all',agency:agencyId='all',unit='all',role='direction',companyName='votre ESN'}={}){
  const p=['week','month','quarter','semester'].includes(period)?period:'week',org=activeOrganization(organization),current=periodKey(todayISO(),p);
  const selectedUnit=unit==='all'?null:org.units.find(item=>item.id===unit),selectedAgency=agencyId==='all'?null:org.agencies.find(item=>item.id===agencyId),selectedCity=city==='all'?'all':city;
  const person=id=>org.people.find(p=>p.id===id);
  const agency=id=>org.agencies.find(a=>a.id===id);
  const events=activityEvents(normalizeWorkflow(workflow)).filter(item=>periodKey(item.date,p)===current&&(!selectedAgency||item.agencyId===selectedAgency.id)&&(!selectedUnit||item.unitId===selectedUnit.id)&&(selectedCity==='all'||agency(item.agencyId)?.city===selectedCity)).sort((a,b)=>b.date.localeCompare(a.date));
  const rows=events.map(item=>({...item,person:person(item.ownerId)?.name||'Responsable non attribué',personRole:person(item.ownerId)?.role||'Non renseigné',agency:agency(item.agencyId)?.name||'Sans agence',city:agency(item.agencyId)?.city||'Ville non renseignée',unit:org.units.find(u=>u.id===item.unitId)?.name||'BU non renseignée'}));
  const totals=Object.fromEntries(Object.keys(labels).map(kind=>[kind,rows.filter(row=>row.kind===kind).reduce((sum,row)=>sum+row.count,0)]));
  const owners=[...new Set(rows.map(row=>row.ownerId||'unassigned'))].map(id=>({id,name:person(id==='unassigned'?null:id)?.name||'Responsable non attribué',events:rows.filter(row=>(row.ownerId||'unassigned')===id)}));
  return {id:globalThis.crypto?.randomUUID?.()||`report-${Date.now()}`,generatedAt:new Date().toISOString(),companyName,role,period:p,key:current,city:selectedCity,agencyId:selectedAgency?.id||'all',agencyName:selectedAgency?.name||'Toutes les agences',unitId:selectedUnit?.id||'all',unitName:selectedUnit?.name||'Toutes les BU',rows,totals,owners,source:'Journal des actions et volumes consignés dans cet espace'};
}

export function activityReportCsv(report){
  const header=['Généré le (heure de Paris)','Date','Type','Volume déclaré','Intitulé','Responsable','Fonction','Ville','Agence','BU','Source'];
  return '\ufeff'+[header,...report.rows.map(row=>[formatReportTimestamp(report.generatedAt),row.date,labels[row.kind],row.count,row.title,row.person,row.personRole,row.city,row.agency,row.unit,row.source])].map(row=>row.map(csv).join(';')).join('\r\n');
}

export function activityReportEmail(report,companyName='votre ESN'){
  const total=Object.values(report.totals).reduce((sum,n)=>sum+n,0);
  return `Objet : Activité déclarée · ${companyName} · ${periodLabel(report.period).toLowerCase()}\n\nBonjour,\n\nVoici le rapport d’activité généré le ${formatReportTimestamp(report.generatedAt)} pour ${companyName} (${report.key}).\nPérimètre : ${report.city==='all'?'Toutes les villes':report.city} · ${report.agencyName} · ${report.unitName} · rôle ${report.role}.\n\nE-mails déclarés : ${report.totals.email}\nApproches LinkedIn déclarées : ${report.totals.linkedin}\nActions marquées terminées : ${report.totals.action}\nRendez-vous marqués tenus : ${report.totals.meeting}\nTotal des activités consignées : ${total}\n\n${report.owners.length?report.owners.map(owner=>`${owner.name} : ${owner.events.reduce((sum,event)=>sum+event.count,0)} activité${owner.events.reduce((sum,event)=>sum+event.count,0)>1?'s':''} consignée${owner.events.reduce((sum,event)=>sum+event.count,0)>1?'s':''}`).join('\n'):'Aucune activité consignée sur cette période.'}\n\nDéfinitions : e-mails et LinkedIn = volumes consignés ; action = statut terminé ; rendez-vous = statut tenu. Aucun taux de conversion déduit.\nSource : ${report.source}.\n\nAperçu uniquement : aucun e-mail n’est envoyé.`;
}

export function renderActivityReportSetup(organization,{period='week',city='all',agency='all',unit='all',reports=[]}={}){
  const org=activeOrganization(organization),cities=[...new Set([...org.agencies.map(a=>a.city),...(city==='all'?[]:[city])])].sort((a,b)=>a.localeCompare(b,'fr'));
  const agencies=org.agencies.filter(a=>city==='all'||a.city===city);
  const units=org.units.filter(u=>agencies.some(a=>a.id===u.agencyId)&&(agency==='all'||u.agencyId===agency));
  return `<section class="glass card activity-report-setup"><div class="eyebrow">ADMINISTRATION · ACTIVITÉ</div><h2>Générer le rapport d’activité.</h2><p>Choisissez la période, la ville et la BU. Le rapport conserve les activités datées et leur source au moment de sa génération.</p><div class="activity-report-controls"><label>Période <select class="pw-period-select" data-change="report-period">${[['week','Semaine'],['month','Mois'],['quarter','Trimestre'],['semester','Semestre']].map(([id,label])=>`<option value="${id}" ${period===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Ville <select data-change="report-city"><option value="all">Toutes les villes</option>${cities.map(name=>`<option value="${safe(name)}" ${city===name?'selected':''}>${safe(name)}</option>`).join('')}</select></label><label>Agence <select data-change="report-agency"><option value="all">Toutes les agences</option>${agencies.map(a=>`<option value="${safe(a.id)}" ${agency===a.id?'selected':''}>${safe(a.name)}</option>`).join('')}</select></label><label>BU <select data-change="report-unit"><option value="all">Toutes les BU</option>${units.map(u=>`<option value="${safe(u.id)}" ${unit===u.id?'selected':''}>${safe(u.name)}</option>`).join('')}</select></label><button type="button" class="btn btn-primary" data-action="report-generate">Générer le rapport →</button></div><p class="panel-footnote">Définitions : prospection = volumes e-mail ou LinkedIn déclarés ; action = marquée terminée ; RDV = marqué tenu. Aucun taux de conversion n’est extrapolé.</p></section>${reports.length?`<section class="glass card activity-report-saved"><div class="section-title"><div><h2>Rapports enregistrés</h2><p>Chaque document garde sa date et son périmètre à la génération.</p></div></div>${reports.slice().reverse().map(report=>`<button type="button" data-action="report-select" data-id="${safe(report.id)}"><strong>${periodLabel(report.period)} · ${safe(report.key)}</strong><span>${safe(report.city==='all'?'Toutes les villes':report.city)} · ${safe(report.agencyName)} · ${safe(report.unitName)} · ${safe(formatReportTimestamp(report.generatedAt))}</span><span>Consulter →</span></button>`).join('')}</section>`:''}`;
}

export function activityReportHtml(report,companyName='votre ESN',baseUrl=''){
  const route=kind=>kind==='meeting'?'#agenda':kind==='action'?'#team?tab=plans':'#team?tab=activite';
  const url=kind=>baseUrl?`${baseUrl}${route(kind)}`:route(kind);
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rapport d’activité · ${safe(companyName)}</title><style>body{font:15px/1.5 system-ui,sans-serif;color:#252532;background:#f3f3f7;margin:0;padding:40px}main{max-width:1000px;margin:auto;background:white;border:1px solid #e6e3ee;border-radius:18px;padding:36px}h1{font-size:36px;letter-spacing:-.04em;margin:8px 0}.meta{color:#666378}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:28px 0}.summary div{border:1px solid #e7e3ee;border-radius:12px;padding:16px}.summary strong{display:block;font-size:30px}table{border-collapse:collapse;width:100%}th,td{text-align:left;border-bottom:1px solid #e8e5ed;padding:10px;vertical-align:top}small{color:#666378}a{color:#5944c9}footer{margin-top:24px;color:#666378}@media(max-width:700px){body{padding:12px}main{padding:18px}.summary{grid-template-columns:repeat(2,1fr)}table{display:block;overflow-x:auto}}@media print{body{padding:0;background:white}main{border:0;padding:0}}</style></head><body><main><p class="meta">BELLUMAI · RAPPORT D’ACTIVITÉ · ${safe(formatReportTimestamp(report.generatedAt))}</p><h1>Activité déclarée</h1><p>${safe(companyName)} · ${safe(periodLabel(report.period))} (${safe(report.key)}) · ${safe(report.city==='all'?'Toutes les villes':report.city)} · ${safe(report.agencyName)} · ${safe(report.unitName)} · rôle ${safe(report.role)}</p><div class="summary">${Object.entries(labels).map(([id,label])=>`<div><span>${safe(label)}</span><strong>${report.totals[id]||0}</strong></div>`).join('')}</div><h2>Activités documentées</h2><table><thead><tr><th>Date</th><th>Activité</th><th>Volume</th><th>Responsable / territoire</th><th>Source</th></tr></thead><tbody>${report.rows.map(row=>`<tr><td>${safe(row.date)}</td><td>${safe(row.title)}<br><small>${safe(labels[row.kind])}</small></td><td>${row.count}</td><td>${safe(row.person)} · ${safe(row.personRole)}<br><small>${safe(row.city)} · ${safe(row.agency)} · ${safe(row.unit)}</small></td><td><a href="${safe(url(row.kind))}">Ouvrir la page des saisies</a><br><small>${safe(row.source)}</small></td></tr>`).join('')||'<tr><td colspan="5">Aucune activité sur ce périmètre et cette période.</td></tr>'}</tbody></table><footer><strong>Définitions.</strong> E-mail et LinkedIn : volumes consignés, sans vérification d’envoi. Action : statut terminé. Rendez-vous : statut tenu. Aucun taux de conversion déduit.<br>${safe(report.source)}. Document figé à la génération ; aucun e-mail envoyé.</footer></main></body></html>`;
}

export function renderActivityReport(report,{channel='all',owner='all',preview=false,companyName='votre ESN'}={}){
  const activeChannel=Object.hasOwn(labels,channel)?channel:'all',activeOwner=report.owners.some(x=>x.id===owner)?owner:'all';
  const ownerRows=report.rows.filter(row=>activeOwner==='all'||(row.ownerId||'unassigned')===activeOwner);
  const scopedTotals=Object.fromEntries(Object.keys(labels).map(kind=>[kind,ownerRows.filter(row=>row.kind===kind).reduce((sum,row)=>sum+row.count,0)]));
  const filtered=ownerRows.filter(row=>activeChannel==='all'||row.kind===activeChannel);
  const chartKinds=Object.entries(labels).filter(([id])=>activeChannel==='all'||id===activeChannel);
  const max=Math.max(1,...chartKinds.map(([id])=>scopedTotals[id]));
  return `<section class="glass card activity-report" aria-labelledby="report-title"><div class="section-title"><div><div class="eyebrow">ADMINISTRATION · DOCUMENT FIGÉ</div><h2 id="report-title">Rapport d’activité</h2><p>${periodLabel(report.period)} · ${safe(companyName)} · e-mails, LinkedIn, actions terminées et rendez-vous tenus. Aucun taux de conversion extrapolé.</p></div></div><div class="activity-report-meta"><span>Généré le ${safe(formatReportTimestamp(report.generatedAt))}</span><span>${safe(report.city==='all'?'Toutes les villes':report.city)} · ${safe(report.agencyName)} · ${safe(report.unitName)}</span><span>Rôle : ${safe(report.role)}</span></div><div class="activity-report-controls"><button class="btn btn-quiet" type="button" data-action="report-new">Préparer un autre rapport</button><button class="btn btn-quiet" type="button" data-action="report-preview" aria-expanded="${preview}">${preview?'Masquer l’aperçu':'Aperçu e-mail'}</button><button class="btn btn-quiet" type="button" data-action="report-export">Exporter CSV</button><button class="btn btn-primary" type="button" data-action="report-open">Ouvrir le document HTML</button></div><p class="panel-footnote">Graphique et filtres de canaux : ${activeOwner==='all'?'toute l’équipe du document':'responsable sélectionné'}. Le document exporté conserve son périmètre initial.</p><div class="series-filter" role="group" aria-label="Filtrer le rapport par canal"><button type="button" data-action="report-series" data-value="all" class="${activeChannel==='all'?'active':''}" aria-pressed="${activeChannel==='all'}">Toutes les séries</button>${Object.entries(labels).map(([id,label])=>`<button type="button" data-action="report-series" data-value="${id}" class="${activeChannel===id?'active':''}" aria-pressed="${activeChannel===id}">${label} · ${scopedTotals[id]}</button>`).join('')}</div><div class="activity-report-chart" role="group" aria-label="Répartition des activités consignées">${chartKinds.map(([id,label])=>`<button type="button" class="activity-report-bar ${activeChannel===id?'active':''}" data-action="report-series" data-value="${id}"><span>${label}</span><span class="activity-report-track"><i style="width:${scopedTotals[id]?Math.round(scopedTotals[id]/max*100):0}%"></i></span><strong>${scopedTotals[id]}</strong></button>`).join('')}</div><div class="activity-report-owners" role="group" aria-label="Filtrer par responsable"><button type="button" data-action="report-owner" data-value="all" class="${activeOwner==='all'?'active':''}">Toute l’équipe</button>${report.owners.map(item=>`<button type="button" data-action="report-owner" data-value="${safe(item.id)}" class="${activeOwner===item.id?'active':''}">${safe(item.name)} · ${item.events.reduce((sum,event)=>sum+event.count,0)}</button>`).join('')}</div><div class="activity-report-details"><div class="section-title"><div><h3>Activités documentées</h3><p>Chaque ligne reprend une activité consignée ou un statut validé.</p></div></div>${filtered.length?filtered.map(item=>`<div class="activity-report-row"><time>${safe(item.date)}</time><span><strong>${safe(item.title)}</strong><small>${safe(item.person)} · ${safe(item.personRole)} · ${safe(item.city)} · ${safe(item.agency)} · ${safe(item.unit)} · ${safe(item.source)}</small></span><b>${item.count} ${safe(labels[item.kind])}<button type="button" class="text-button" data-action="report-source" data-kind="${item.kind}" data-id="${safe(item.id)}" data-date="${safe(item.date)}">Voir la source →</button></b></div>`).join(''):'<p class="body-copy">Aucune activité sur ce filtre. Consignez une prospection, terminez une action ou marquez un rendez-vous tenu pour alimenter le rapport.</p>'}</div>${preview?`<div class="activity-report-email"><div><strong>Aperçu e-mail · aucun envoi</strong><button type="button" class="text-button" data-action="report-copy">Copier le texte →</button></div><pre>${safe(activityReportEmail(report,companyName))}</pre></div>`:''}<p class="panel-footnote">Document figé lors de la génération. Les filtres de série et de responsable ne modifient pas l’export. Aucun message envoyé.</p></section>`;
}
